(window.webpackJsonp=window.webpackJsonp||[]).push([[249],{754:function(e,n,s){"use strict";s.r(n);var a=s(33),t=Object(a.a)({},function(){var e=this,n=e.$createElement,s=e._self._c||n;return s("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[s("h1",{attrs:{id:"principen-for-plasmasvetsning"}},[s("a",{staticClass:"header-anchor",attrs:{href:"#principen-for-plasmasvetsning","aria-hidden":"true"}},[e._v("#")]),e._v(" Principen för plasmasvetsning")]),e._v(" "),s("p",[e._v("Plasma är det fjärde aggregationstillståndet, övriga är fast, -flytande och -gasform. När gasen övergår till plasmafas i en ljusbåge vid svetsning, får man i jämförelse med TIG-svetsning ett högre värmeinnehåll och energitäthet samt bättre stabilitet hos ljusbågen. Detta medför att svetsning kan ske i tunna godstjocklekar, samt även svetsning av grövre godstjocklekar där metoden ger en god produktionsekonomi.")]),e._v(" "),s("p",[e._v("Plasmasvetsning (PAW) är en vidareutveckling av TIG-svetsning.")]),e._v(" "),s("p",[e._v("Den indragna elektroden är av samma typ som för TIG med likström, volfram med 2 % toriumoxid, och ansluten till minuspol, se bild 1.")]),e._v(" "),s("p",[s("img",{attrs:{src:"https://eu1files.itslearning.com/data/1821/C9373/Plasmab%C3%A5gsvetsning.png",alt:""}})]),e._v(" "),s("p",[e._v("Plasmagasen leds in i plasmadysen, där elektroden finns indragen och omsluten av vattenkylda dysen. Plasmagasen får då formen av en nästan cylindrisk pelare när upphettning och expansion av gasen sker. Sedan tvingas plasmagasen med hög hastighet ut genom centrumhålet i dysan.")]),e._v(" "),s("p",[e._v("Plasman består av en joniserad gasblandning som når en temperatur av över 20 000 ºC. Principen är att en gasblandning strömmar ut genom det inre munstycket. Den hettas upp starkt i ljusbågen varvid den dissocieras och delvis joniseras. Genom det yttre munstycket strömmar en skyddsgas som skyddar smältan mot oxidation.")]),e._v(" "),s("p",[e._v("Plasmagas och skyddsgas utgörs som regel av argon med ca 5 % hydrogen. Vid mikroplasmametoden används emellertid ren argon som plasmagas och en blandning av argon och hydrogen som skyddsgas. En hjälpbåge eller pilotbåge, som brinner mellan elektrod och munstycke, underlättar tändningen och lyser dessutom upp arbetsstycket. Som strömkälla används som regel likström.")]),e._v(" "),s("h1",{attrs:{id:"anvandning"}},[s("a",{staticClass:"header-anchor",attrs:{href:"#anvandning","aria-hidden":"true"}},[e._v("#")]),e._v(" Användning")]),e._v(" "),s("p",[e._v('Plasmasvetsning används främst vid svetsning av olika typer av rostfria stål och icke- järnmetaller. Plasmabågsvetsningen har utvecklats till en helautomatisk metod för svetsning av bl.a. rostfria rör. Godstjockleken är vanligen 2–7 mm. Plasmasvetsning är mest fördelaktig när det gäller godstjocklekar över 2,5 mm där man kan använda den s.k. "key-hole"-tekniken (nyckelhålstekniken), vilket innebär att den smala plasmastrålen smälter ett hål genom plåten, se bild.')]),e._v(" "),s("p",[s("img",{attrs:{src:"https://eu1files.itslearning.com/data/1821/C9373/Plasmab%C3%A5gsvetsning%202.png",alt:""}})])])},[],!1,null,null,null);n.default=t.exports}}]);